export function getCoursesForDiscipline(disciplineSlug: string): OutlineCourse[] {
  return outlineCourses.filter((course) => course.disciplineSlug === disciplineSlug);
}

export function getOutlineCourse(
  disciplineSlug: string,
  courseSlug: string,
): OutlineCourse | undefined {
  return outlineCourses.find(
    (course) => course.disciplineSlug === disciplineSlug && course.slug === courseSlug,
  );
}

export function getOutlineLesson(
  disciplineSlug: string,
  courseSlug: string,
  lessonSlug: string,
): OutlineLesson | undefined {
  return getOutlineCourse(disciplineSlug, courseSlug)?.lessons.find(
    (lesson) => lesson.slug === lessonSlug,
  );
}
